   <body>
     <a class="skip-link" href="#main-content">Skip to main content</a>
     <div class="page-shell">
       <header>
         <p class="eyebrow">Multi-select quiz</p>
         <h1>Computer Languages Quiz</h1>
         <p class="intro">
           Test your language knowledge. Some questions may have more than one
           correct answer, so choose every option that applies.
         </p>
       </header>

       <main id="main-content">
         <section class="quiz-card" aria-labelledby="quiz-heading">
           <h2 id="quiz-heading" class="visually-hidden">Quiz questions</h2>
           <form id="quiz-form">
             <div id="quiz-root"></div>
             <div class="actions">
               <button type="submit">Submit answers</button>
               <p id="quiz-result" class="result" aria-live="polite"></p>
             </div>
           </form>
         </section>
       </main>
     </div>

     <script>
       const questions = [
         {
           id: "compiled",
           prompt: "Which of these languages are commonly compiled before running?",
           help:
             "Select all languages that are typically transformed into machine code, bytecode, or another executable form before the program runs.",
           choices: ["C", "Java", "Python", "Go"],
         },
         {
           id: "web",
           prompt: "Which languages are commonly used to build web applications?",
           choices: ["JavaScript", "Ruby", "Swift", "PHP"],
         },
         {
           id: "typed",
           prompt: "Which languages are known for static type checking?",
           choices: ["TypeScript", "Rust", "HTML", "Kotlin"],
         },
       ];

       function Choice({ questionId, choice, index }) {
         const inputId = `${questionId}-${index}`;

         return `
           <label class="choice" for="${inputId}">
             <input
               id="${inputId}"
               type="checkbox"
               name="${questionId}"
               value="${choice}"
             >
             <span class="choice-label">${choice}</span>
           </label>
         `;
       }

       function QuestionField({ id, prompt, help, choices }, index) {
         const helpId = help ? `${id}-help` : "";
         const describedBy = help ? ` aria-describedby="${helpId}"` : "";

         return `
           <div class="form-field">
             <fieldset${describedBy}>
               <legend>${index + 1}. ${prompt}</legend>
               ${
                 help
                   ? `<p id="${helpId}" class="help-text">${help}</p>`
                   : ""
               }
               <div class="choice-grid">
                 ${choices
                   .map((choice, choiceIndex) =>
                     Choice({ questionId: id, choice, index: choiceIndex })
                   )
                   .join("")}
               </div>
             </fieldset>
           </div>
         `;
       }

       function QuizApp({ questions }) {
         return questions.map(QuestionField).join("");
       }

       document.getElementById("quiz-root").innerHTML = QuizApp({ questions });

       document.getElementById("quiz-form").addEventListener("submit", (event) => {
         event.preventDefault();

         const selectedCount = new FormData(event.currentTarget)
           .getAll("compiled")
           .concat(new FormData(event.currentTarget).getAll("web"))
           .concat(new FormData(event.currentTarget).getAll("typed")).length;

         document.getElementById("quiz-result").textContent =
           selectedCount === 0
             ? "No answers selected yet."
             : `Answers submitted with ${selectedCount} selection${
                 selectedCount === 1 ? "" : "s"
               }.`;
       });
     </script>
   </body>
 </html>

